#!/usr/bin/env bash
#
# Generates the boot splash from splash.svg (240 x 240, on black), quantized to the
# 224 colors of the kernel's logo format, into:
# - splash.ppm: the kernel's boot logo, which fbcon draws in the middle of the
#   screen as soon as the display is up (external.mk puts it in the kernel tree)
# - src/splash_image.c: the same pixels as a PNG, phone-ui's first frame at the same
#   place (splash.c), which then fades into the home screen
#
# After running it: `just make linux-rebuild phone-ui-rebuild all`, then flash.
#
# Run in `nix develop` (resvg, ImageMagick):
#   external/package/phone-ui/gen-splash.sh
#

set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

resvg "$here/splash.svg" "$tmp/splash.png"
# Opaque black background, no dithering: the edges keep their antialiasing colors
magick "$tmp/splash.png" -background black -alpha remove -alpha off +dither -colors 224 \
	"$tmp/quantized.png"
magick "$tmp/quantized.png" -depth 8 -compress none "ppm:$here/splash.ppm" # ASCII: the kernel reads no other
magick "$tmp/quantized.png" -depth 8 "PNG24:$tmp/out.png"

{
	echo "/* Generated by gen-splash.sh from splash.svg, do not edit */"
	echo
	echo "#include \"ui.h\""
	echo
	echo "const uint8_t ui_splash_png[] = {"
	od -An -v -tx1 "$tmp/out.png" | sed -e 's/ \([0-9a-f][0-9a-f]\)/0x\1, /g' -e 's/ *$//' -e 's/^/\t/'
	echo "};"
	echo "const unsigned ui_splash_png_size = sizeof(ui_splash_png);"
} > "$tmp/splash_image.c"
mv "$tmp/splash_image.c" "$here/src/splash_image.c"
